package okhttp3;import java.io.IOException;public class Call {public boolean canceled;public Callback callback;public Request request;public Call(Request r){request=r;}public void cancel(){canceled=true;}public void enqueue(Callback cb){callback=cb;}public void succeed(String text){callback.onResponse(this,new Response(200,new ResponseBody(text)));}public void respond(int status,String text){callback.onResponse(this,new Response(status,new ResponseBody(text)));}public void fail(){callback.onFailure(this,new IOException("offline"));}}
